import requests, sys, uuid, time, json

BASE = '{{TESTVDB_DB_URL}}'
HEADERS = {'Authorization': '{{TESTVDB_AUTH_HEADER}}', 'Content-Type': 'application/json'}

# First create a collection with data to set up preconditions
c = 'test_' + uuid.uuid4().hex[:8]
print(f"Creating collection {c}...")

# Create collection
payload = {
    "collectionName": c,
    "schema": {
        "autoID": False,
        "enableDynamicField": True,
        "fields": [
            {"fieldName": "id", "dataType": "Int64", "isPrimary": True},
            {"fieldName": "vector", "dataType": "FloatVector", "elementTypeParams": {"dim": 4}}
        ]
    },
    "indexParams": [
        {"fieldName": "vector", "metricType": "COSINE", "indexType": "AUTOINDEX"}
    ]
}
r = requests.post(f'{BASE}/v2/vectordb/collections/create', headers=HEADERS, json=payload)
print(f"Create response: {r.status_code} {r.text[:200]}")
assert r.json().get('code') == 0, f"Create failed: {r.text}"
time.sleep(0.5)

# Insert some data
r = requests.post(f'{BASE}/v2/vectordb/entities/insert', headers=HEADERS, json={
    "collectionName": c,
    "data": [{"id": 1, "vector": [0.1, 0.2, 0.3, 0.4]}]
})
print(f"Insert response: {r.status_code} {r.text[:200]}")
assert r.json().get('code') == 0, f"Insert failed: {r.text}"
time.sleep(0.3)

# Load collection
r = requests.post(f'{BASE}/v2/vectordb/collections/load', headers=HEADERS, json={
    "collectionName": c
})
print(f"Load response: {r.status_code} {r.text[:200]}")
time.sleep(0.5)

# TEST 1: collectionName=null on /v2/vectordb/entities/query
print("\n=== TEST 1: collectionName=null on /v2/vectordb/entities/query ===")
r = requests.post(f'{BASE}/v2/vectordb/entities/query', headers=HEADERS, json={
    "collectionName": None,
    "filter": "id > 0",
    "limit": 10,
    "outputFields": ["id"]
})
print(f"Response: {r.status_code} {r.text[:500]}")
code = r.json().get('code', -1)
if code == 0:
    print("[DEFECT: ILLEGAL_SUCCESS] Server accepted collectionName=null")
    sys.exit(1)
e

